const maxRows = 100;
// UTF-8 uses at most three bytes per UTF-16 code unit. Leave room under the
// 1,500,000 byte API limit for JSON serialization and transport.
const maxJsonLength = 400_000;
const resumeTracks = { admin: "admin", excel: "admin", web: "web", engineering: "engineering" };

function requiredText(value, field, limit) {
  if (typeof value !== "string" || !value.trim() || value.trim().length > limit) {
    throw new Error(`Invalid Quantself import field: ${field}.`);
  }
  return value.trim();
}

function importRow(candidate) {
  const sourceUrl = requiredText(candidate.sourceUrl, "sourceUrl", 2_048);
  // Source adapters validate public hosts and canonicalize the posting URL.
  if (!/^https?:\/\/[a-z\d-]+(?:\.[a-z\d-]+)+(?::\d+)?(?:[/?#]|$)/i.test(sourceUrl)) {
    throw new Error("Invalid Quantself posting URL.");
  }

  const { category, resumeTrack } = candidate;
  if (!Object.hasOwn(resumeTracks, category) || resumeTrack !== resumeTracks[category]) {
    throw new Error("Invalid Quantself résumé track.");
  }

  const fit = requiredText(candidate.fitNote, "fitNote", 240);
  const note = `Fit note (${category}): ${fit}`;
  const posting = typeof candidate.description === "string" ? candidate.description.trim() : "";
  const description = posting
    ? `${note}\n\n${posting.slice(0, 12_000 - note.length - 2).trimEnd()}`
    : note;

  const feedLabel = "n8n Jobs feed";
  const sourceLabel = typeof candidate.sourceLabel === "string" && candidate.sourceLabel.trim()
    ? `${feedLabel} · ${candidate.sourceLabel.trim()}`.slice(0, 120) : feedLabel;

  return {
    company: requiredText(candidate.company, "company", 200),
    role: requiredText(candidate.role, "role", 200),
    sourceUrl,
    track: resumeTrack,
    source: sourceLabel,
    postingText: description,
    ...(typeof candidate.location === "string" && candidate.location.trim()
      ? { location: candidate.location.trim().slice(0, 200) } : {}),
    ...(typeof candidate.salary === "string" && candidate.salary.trim()
      ? { salary: candidate.salary.trim().slice(0, 200) } : {}),
  };
}

function prepareQuantselfBatches(candidates, runId) {
  const executionId = requiredText(runId, "runId", 150);
  if (!/^[a-z0-9_-]+$/i.test(executionId)) throw new Error("Invalid Quantself import run identifier.");
  const seen = new Set();
  const batches = [];
  let applications = [];
  let length = '{"applications":[]}'.length;

  function finishBatch() {
    const body = { applications };
    batches.push({ idempotencyKey: `n8n-jobs-import-${executionId}-${batches.length + 1}`, body });
    applications = [];
    length = '{"applications":[]}'.length;
  }

  for (const candidate of candidates) {
    const identity = requiredText(candidate.sourceIdentity, "sourceIdentity", 2_048);
    if (seen.has(identity)) continue;
    const row = importRow(candidate);
    if (identity.startsWith("greenhouse:global:")) row.sourceIdentity = identity;
    const rowLength = JSON.stringify(row).length + 1;
    if (applications.length >= maxRows || length + rowLength > maxJsonLength) finishBatch();
    applications.push(row);
    length += rowLength;
    seen.add(identity);
  }
  if (applications.length) finishBatch();
  return batches;
}

function summarizeQuantselfImports(batches, responses) {
  if (batches.length !== responses.length) throw new Error("Expected one Quantself response per batch.");
  let imported = 0;
  let duplicates = 0;
  const failedBatches = [];
  const reviewBatches = [];

  for (const [index, batch] of batches.entries()) {
    const { statusCode = null, body } = responses[index] ?? {};
    const count = batch.body.applications.length;
    if (statusCode !== 200 || !Number.isInteger(body?.imported) || !Number.isInteger(body?.duplicates) ||
        body.imported < 0 || body.duplicates < 0 || body.imported + body.duplicates !== count) {
      failedBatches.push({ idempotencyKey: batch.idempotencyKey, statusCode, applications: count });
      continue;
    }
    imported += body.imported;
    duplicates += body.duplicates;
    if (body.imported > 0) reviewBatches.push({
      imported: body.imported,
      duplicates: body.duplicates,
      candidates: batch.body.applications.map(({ company, role, sourceUrl }) => ({ company, role, sourceUrl })),
    });
  }

  return {
    imported,
    duplicates,
    failedBatches,
    tailoring: imported > 0 ? {
      status: "enrichment_queued",
      drafts: imported,
      path: "/jobs/applications",
      reviewBatches,
      action: "Review the imported applications in Jobs after tailoring finishes.",
    } : { status: failedBatches.length ? "import_unconfirmed" : "no_new_drafts", drafts: 0 },
  };
}

const samples = $input.all().map(item => item.json).filter(item => item.usage);
const { quantselfBaseUrl } = $('Feed configuration').first().json;
const { source } = $('Collect postings').first().json;
const kept = samples.flatMap(sample => sample.kept ? [sample.kept] : []);
const batches = prepareQuantselfBatches(kept, $workflow.id + '-' + $execution.id);
const summary = {
  source,
  screening: {
    kept: kept.length,
    skipped: samples.filter(sample => sample.outcome === 'skip').length,
    deferred: source.unique - samples.length,
    errors: samples.filter(sample => !['keep', 'skip'].includes(sample.outcome))
      .map(({ sourceIdentity, outcome, usage }) => ({ sourceIdentity, outcome, requestId: usage.requestId })),
  },
  cost: summarizeModelUsage(samples.map(sample => sample.usage)),
};
return (batches.length ? batches : [null]).map((batch, index) => ({
  json: {
    hasImports: Boolean(batch),
    url: quantselfBaseUrl + '/api/v1/jobs/applications/import',
    index,
    ...batch,
    // Keep one copy of the run summary in order to finalize even with zero imports.
    ...(index === 0 ? { summary } : {}),
  },
}));

function prepareFeedConfig(input) {
  // Avoid relying on WHATWG URL, which is absent in the n8n Code sandbox.
  const baseUrl = typeof input.quantselfBaseUrl === 'string' ? input.quantselfBaseUrl.trim().replace(/\/$/, '') : '';
  if (!/^https:\/\/[a-z\d-]+(?:\.[a-z\d-]+)+(?::\d{1,5})?$/i.test(baseUrl)) {
    throw new Error('Set the Quantself HTTPS origin in Feed configuration.');
  }
  const careerCriteria = typeof input.careerCriteria === 'string' ? input.careerCriteria.trim() : '';
  if (!careerCriteria || careerCriteria.length > 8_000) {
    throw new Error('Set 1 to 8,000 characters of Owner Career criteria in Feed configuration.');
  }
  if (!Array.isArray(input.boards) || !input.boards.length || input.boards.length > 8) {
    throw new Error('Configure 1 to 8 public boards in Feed configuration.');
  }
  if (!Number.isInteger(input.maxScreenings) || input.maxScreenings < 1 || input.maxScreenings > 500) {
    throw new Error('Set maxScreenings between 1 and 500.');
  }
  const { boards, preflight } = input;
  if (preflight != null && (
    typeof preflight !== 'object' || Object.keys(preflight).length !== 2 ||
    boards.length !== 1 || boards[0]?.provider !== 'greenhouse' || boards[0].board !== preflight.board ||
    typeof preflight.board !== 'string' || !/^[a-z\d_-]+$/i.test(preflight.board) ||
    typeof preflight.postingId !== 'string' || !/^[1-9]\d*$/.test(preflight.postingId) ||
    !Number.isSafeInteger(Number(preflight.postingId))
  )) {
    throw new Error('Preflight requires one matching Greenhouse board and a valid posting ID.');
  }
  return { ...input, quantselfBaseUrl: baseUrl, careerCriteria };
}

function preflightUrlParts(sourceUrl, board, postingId) {
  // The Code sandbox lacks WHATWG URL.
  const match = typeof sourceUrl === 'string' &&
    sourceUrl.match(/^(https?):\/\/(?:job-)?boards(?:\.eu)?\.greenhouse\.io(\/[^?#]*)(?:\?([^#]*))?(?:#.*)?$/i);
  if (!match || match[2].replace(/\/+$/, '').toLowerCase() !== `/${board}/jobs/${postingId}`) return;
  return { scheme: match[1].toLowerCase(), query: match[3] ?? '' };
}

function verifyRawPreflightPosting(pages, { board, postingId }) {
  const { jobs, meta } = pages[0]?.body ?? {};
  if (pages.length !== 1 || !Array.isArray(jobs)) {
    throw new Error('Preflight requires exactly one Greenhouse board response.');
  }
  if (meta?.total !== jobs.length) {
    throw new Error('Preflight requires a complete Greenhouse board response with a matching numeric total.');
  }
  // Count claims before normalization can discard malformed rows or deduplicate them.
  const boardToken = board.toLowerCase();
  const matches = jobs.filter(row =>
    String(row?.id) === postingId || preflightUrlParts(row?.absolute_url, boardToken, postingId));
  if (matches.length !== 1 || matches[0].id !== Number(postingId)) {
    throw new Error('Preflight requires exactly one raw row with the approved numeric posting ID and no conflicting URL claims.');
  }
}

function matchesPreflightUrl(sourceUrl, board, postingId) {
  const parts = preflightUrlParts(sourceUrl, board, postingId);
  if (parts?.scheme !== 'https') return false;

  const queryIds = [];
  for (const field of parts.query.split('&')) {
    const [key, ...value] = field.split('=');
    if (decodeURIComponent(key) === 'gh_jid') queryIds.push(decodeURIComponent(value.join('=')));
  }
  return queryIds.length === 0 || (queryIds.length === 1 && queryIds[0] === postingId);
}

function collectPostings(requests, pagesByBoard, normalizeSourceResponse, maxPages, preflight) {
  if (preflight) verifyRawPreflightPosting(pagesByBoard.get(0) ?? [], preflight);

  const postings = new Map();
  const sourceErrors = [];
  let skippedRows = 0;
  let duplicates = 0;
  let responses = 0;

  for (const [index, request] of requests.entries()) {
    const pages = pagesByBoard.get(index) ?? [];
    responses += pages.length;
    const board = `${request.provider}:${request.region}:${request.board}`;
    const boardPostings = [];
    let boardSkipped = 0;
    try {
      if (!pages.length) throw new Error('Missing public board response.');
      const lastPage = pages.at(-1);
      if (request.provider === 'lever' && pages.length === maxPages && lastPage.body?.length >= request.pageSize) {
        throw new Error('Pagination limit reached before the last page.');
      }
      for (const page of pages) {
        const { postings: rows, skipped } = normalizeSourceResponse(request, page);
        boardSkipped += skipped;
        boardPostings.push(...rows);
      }
    } catch (error) {
      sourceErrors.push({ board, reason: error.message });
      continue;
    }
    skippedRows += boardSkipped;
    for (const posting of boardPostings) {
      if (postings.has(posting.sourceIdentity)) duplicates++;
      else postings.set(posting.sourceIdentity, posting);
    }
  }

  const source = { boards: requests.length, responses, unique: postings.size, skippedRows, duplicates, errors: sourceErrors };
  if (!preflight) return { postings: [...postings.values()], source };

  const board = preflight.board.toLowerCase();
  const { postingId } = preflight;
  const selected = postings.get(`greenhouse:global:${board}:${postingId}`);
  if (sourceErrors.length || !matchesPreflightUrl(selected?.sourceUrl, board, postingId)) {
    throw new Error('Preflight could not verify the approved Greenhouse posting URL and identity.');
  }
  return { postings: [selected], source };
}

function selectForScreening(postings, limit, now) {
  const ordered = [...postings].sort((a, b) => a.sourceIdentity.localeCompare(b.sourceIdentity, 'en'));
  if (ordered.length <= limit) return ordered;
  const utcDay = Math.floor(now / 86_400_000);
  const offset = (utcDay * limit) % ordered.length;
  return [...ordered.slice(offset), ...ordered.slice(0, offset)].slice(0, limit);
}

function compactImportResponse(response) {
  const statusCode = Number.isInteger(response?.statusCode) ? response.statusCode : null;
  // Keep only fields needed to interpret a response. HTTP/node errors can include request data.
  const body = response?.body;
  return {
    statusCode,
    body: typeof body === 'object' && body !== null ? {
      imported: body.imported ?? null,
      duplicates: body.duplicates ?? null,
      idempotencyConflict: body.message === 'Idempotency-Key was already used with different input.',
    } : {},
  };
}

function isRetryableImport(response) {
  const { statusCode, body } = response;
  return statusCode === null || (statusCode === 409 && !body.idempotencyConflict)
    || (statusCode >= 500 && statusCode <= 599);
}

const requests = $('Prepare imports').all().map(item => item.json);
const responses = Array(requests.length);
for (const [index, item] of $input.all().entries()) {
  const request = $('Prepare imports').itemMatching(index).json;
  responses[request.index] = compactImportResponse(item.json);
}
const retry = requests.filter((_, index) => isRetryableImport(responses[index] ?? { statusCode: null }));
return (retry.length ? retry : [null]).map((request, index) => ({
  json: {
    ...request, shouldRetry: Boolean(request),
    ...(index === 0 ? { responses } : {}),
  },
}));

function prepareFeedConfig(input) {
  // Avoid relying on WHATWG URL, which is absent in the n8n Code sandbox.
  const baseUrl = typeof input.quantselfBaseUrl === 'string' ? input.quantselfBaseUrl.trim().replace(/\/$/, '') : '';
  if (!/^https:\/\/[a-z\d-]+(?:\.[a-z\d-]+)+(?::\d{1,5})?$/i.test(baseUrl)) {
    throw new Error('Set the Quantself HTTPS origin in Feed configuration.');
  }
  const careerCriteria = typeof input.careerCriteria === 'string' ? input.careerCriteria.trim() : '';
  if (!careerCriteria || careerCriteria.length > 8_000) {
    throw new Error('Set 1 to 8,000 characters of Owner Career criteria in Feed configuration.');
  }
  if (!Array.isArray(input.boards) || !input.boards.length || input.boards.length > 8) {
    throw new Error('Configure 1 to 8 public boards in Feed configuration.');
  }
  if (!Number.isInteger(input.maxScreenings) || input.maxScreenings < 1 || input.maxScreenings > 500) {
    throw new Error('Set maxScreenings between 1 and 500.');
  }
  const { boards, preflight } = input;
  if (preflight != null && (
    typeof preflight !== 'object' || Object.keys(preflight).length !== 2 ||
    boards.length !== 1 || boards[0]?.provider !== 'greenhouse' || boards[0].board !== preflight.board ||
    typeof preflight.board !== 'string' || !/^[a-z\d_-]+$/i.test(preflight.board) ||
    typeof preflight.postingId !== 'string' || !/^[1-9]\d*$/.test(preflight.postingId) ||
    !Number.isSafeInteger(Number(preflight.postingId))
  )) {
    throw new Error('Preflight requires one matching Greenhouse board and a valid posting ID.');
  }
  return { ...input, quantselfBaseUrl: baseUrl, careerCriteria };
}

function preflightUrlParts(sourceUrl, board, postingId) {
  // The Code sandbox lacks WHATWG URL.
  const match = typeof sourceUrl === 'string' &&
    sourceUrl.match(/^(https?):\/\/(?:job-)?boards(?:\.eu)?\.greenhouse\.io(\/[^?#]*)(?:\?([^#]*))?(?:#.*)?$/i);
  if (!match || match[2].replace(/\/+$/, '').toLowerCase() !== `/${board}/jobs/${postingId}`) return;
  return { scheme: match[1].toLowerCase(), query: match[3] ?? '' };
}

function verifyRawPreflightPosting(pages, { board, postingId }) {
  const { jobs, meta } = pages[0]?.body ?? {};
  if (pages.length !== 1 || !Array.isArray(jobs)) {
    throw new Error('Preflight requires exactly one Greenhouse board response.');
  }
  if (meta?.total !== jobs.length) {
    throw new Error('Preflight requires a complete Greenhouse board response with a matching numeric total.');
